<?php
declare(strict_types=1);
define('PLEKSI_APP',true);require __DIR__.'/app/core.php';require __DIR__.'/app/accounts.php';
header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store');
if(is_file(__DIR__.'/app/config.php')){http_response_code(403);echo '<!doctype html><html lang="tr"><meta charset="utf-8"><title>Kurulum tamamlandı</title><p>Kurulum daha önce tamamlanmış. Güvenlik için yeniden kurulum kapalı.</p><a href="./">Mağazaya dön</a></html>';exit;}
$extensions=['pdo_mysql','mbstring','curl','simplexml','dom','fileinfo','iconv'];$checks=['PHP 8.2 veya üzeri'=>PHP_VERSION_ID>=80200,'app/ klasörüne yazma izni'=>is_writable(__DIR__.'/app'),'Hazır arayüz dosyaları'=>is_file(__DIR__.'/app/frontend.html')];foreach($extensions as $extension)$checks[$extension.' uzantısı']=extension_loaded($extension);
$secure=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Strict']);session_start();$_SESSION['install_token']??=bin2hex(random_bytes(32));$error='';$success=false;
$path=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/install.php')),'/.');$suggest=($secure?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').$path;
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 $ownedLock=false;$createdConfig=false;
 try{
  if(!hash_equals($_SESSION['install_token'],(string)($_POST['token']??'')))fail('Kurulum oturumu geçersiz. Sayfayı yenileyin.');if(in_array(false,$checks,true))fail('Önce sunucu gereksinimlerini tamamlayın.');
  $dbHost=trim((string)($_POST['db_host']??''));$dbPort=(int)($_POST['db_port']??3306);$dbName=trim((string)($_POST['db_name']??''));$dbUser=trim((string)($_POST['db_user']??''));$dbPass=(string)($_POST['db_pass']??'');
  if(!preg_match('/^[a-zA-Z0-9_.:-]+$/D',$dbHost)||!preg_match('/^[a-zA-Z0-9_$-]+$/D',$dbName)||$dbUser===''||$dbPort<1||$dbPort>65535)fail('Veritabanı sunucusu, adı, kullanıcısı ve portunu kontrol edin.');
  $site=rtrim(trim((string)($_POST['site_url']??'')),'/');$parts=parse_url($site);if(!is_array($parts)||!in_array($parts['scheme']??'',['http','https'],true)||empty($parts['host'])||isset($parts['user'])||isset($parts['query'])||isset($parts['fragment'])||!preg_match('~^(?:/[a-zA-Z0-9_.-]+)*$~D',$parts['path']??'')||preg_match('~/(?:\.|\.\.)(?:/|$)~',$parts['path']??''))fail('Geçerli site adresini yazın. Alt klasör varsa adresin sonuna ekleyin.');
  $ph=phone($_POST['phone']??null);foreach(['first_name','last_name','city','district','neighborhood'] as $key)if(!valid_text($_POST[$key]??null))fail('Yönetici isim ve adres bilgilerini doldurun.');if(!$ph||!good_password($_POST['password']??null)||$_POST['password']!==($_POST['password_confirm']??''))fail('Telefonu ve eşleşen en az 10 karakterli şifreleri kontrol edin.');
  $lock=@fopen(__DIR__.'/app/install.lock','x');if(!$lock)fail('Kurulum kilitli. Başka bir kurulum çalışmıyorsa ve kurulum tamamlanmadıysa app/install.lock dosyasını kontrol edin.');$ownedLock=true;fclose($lock);chmod(__DIR__.'/app/install.lock',0600);
  $db=new PDO("mysql:host=$dbHost;port=$dbPort;dbname=$dbName;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$db->exec("SET time_zone='+00:00'");
  $exists=$db->query("SHOW TABLES LIKE 'ph_users'")->fetchColumn();if($exists&&(int)$db->query('SELECT COUNT(*) FROM ph_users')->fetchColumn()>0)fail('Bu veritabanında mevcut üyeler var. Verilerin üzerine kurulum yapılmadı; boş bir veritabanı seçin.');
  $schema=file_get_contents(__DIR__.'/app/schema.sql');foreach(explode(';',$schema) as $statement)if(trim($statement)!=='')$db->exec($statement);
  $config=['db_host'=>$dbHost,'db_port'=>$dbPort,'db_name'=>$dbName,'db_user'=>$dbUser,'db_pass'=>$dbPass,'site_url'=>$site,'base_path'=>$parts['path']??'','secure_cookie'=>$parts['scheme']==='https','app_key'=>bin2hex(random_bytes(32))];
  $configText="<?php\ndeclare(strict_types=1);\nif(!defined('PLEKSI_APP')){http_response_code(404);exit;}\nreturn ".var_export($config,true).";\n";$temp=__DIR__.'/app/config.'.bin2hex(random_bytes(8)).'.tmp.php';$f=@fopen($temp,'x');if(!$f)fail('Yapılandırma dosyası yazılamadı. app/ yazma izinlerini kontrol edin.');chmod($temp,0600);if(fwrite($f,$configText)!==strlen($configText)){fclose($f);unlink($temp);fail('Yapılandırma dosyası tamamlanamadı.');}fclose($f);
  try{atomic(function()use($ph,$temp,&$createdConfig){sql("INSERT INTO ph_users(phone,name,first_name,last_name,city,district,neighborhood,password,role,dealer_status) VALUES(?,?,?,?,?,?,?,?,'admin','approved')",[$ph,trim($_POST['first_name']).' '.trim($_POST['last_name']),trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['city']),trim($_POST['district']),trim($_POST['neighborhood']),pass_hash($_POST['password'])]);set_setting('admin_whatsapp',$ph);set_setting('delivery_fees',enc(['pickup'=>0,'cargo'=>0,'address'=>0]));if(isset($_POST['seed']))foreach(dec(file_get_contents(__DIR__.'/app/seed.json')) as $p){unset($p['id'],$p['dealerPrice']);save_product($p);}if(is_file(__DIR__.'/app/config.php')||!rename($temp,__DIR__.'/app/config.php'))fail('Kurulum yapılandırması kaydedilemedi.');$createdConfig=true;});}catch(Throwable $e){if(is_file($temp))unlink($temp);if($createdConfig)unlink(__DIR__.'/app/config.php');throw $e;}
  $_SESSION=[];session_destroy();$success=true;
 }catch(ApiError $e){$error=$e->getMessage();if($ownedLock&&!$success)@unlink(__DIR__.'/app/install.lock');}
 catch(Throwable $e){$error='Veritabanı bağlantısı veya kurulum tamamlanamadı. Bilgileri, kullanıcı yetkilerini ve hosting PHP hata günlüğünü kontrol edin.';error_log('Pleksi kurulum: '.$e::class.' [kurulum tamamlanamadı]');if($ownedLock&&!$success)@unlink(__DIR__.'/app/install.lock');}
}
function val(string $k,string $default=''): string {return esc(is_string($_POST[$k]??null)?$_POST[$k]:$default);}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pleksi Hediye · PHP Kurulumu</title><style>*{box-sizing:border-box}body{margin:0;background:#f8f3ed;color:#352c2c;font:14px/1.6 Arial,sans-serif}.wrap{max-width:760px;margin:45px auto;padding:30px;background:#fffdfa;border:1px solid #eaded2;border-radius:16px}.logo{font-size:32px;letter-spacing:-1.7px;font-weight:bold}.logo span{color:#ee85a9}.eyebrow{font-size:10px;letter-spacing:2px;color:#b48992;margin-top:10px}h1{font-weight:400;letter-spacing:-1px;font-size:29px}h2{font-size:16px;margin-top:28px}.sub{font-size:12px;color:#9a8373}label{display:block;font-size:12px;margin:15px 0}input{display:block;width:100%;padding:12px;border:1px solid #decfc1;background:#fffcf6;border-radius:6px;margin-top:6px;font:inherit}input[type=checkbox]{width:auto;display:inline;margin-right:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.checks{display:flex;flex-wrap:wrap;gap:7px;margin:20px 0}.check{font-size:10px;padding:5px 8px;border-radius:4px;background:#eaf0e5;color:#6c825e}.check.fail{background:#f8e2e2;color:#a45e6c}.error{padding:15px;background:#f8e1e3;border-radius:6px;color:#9c465d;font-size:12px}.button{display:block;width:100%;padding:15px;background:#352c2c;color:#fff5ee;text-align:center;border:0;border-radius:7px;text-decoration:none;font:inherit;cursor:pointer;margin-top:25px}.button:disabled{opacity:.4;cursor:not-allowed}.success{padding:25px;background:#edf3e7;border-radius:7px}code{background:#f3e9e1;padding:2px 5px}@media(max-width:600px){.wrap{margin:15px;padding:23px}.grid{grid-template-columns:1fr}.logo{font-size:28px}}</style></head><body><main class="wrap"><div class="logo">pleksi<span>hediye</span></div><div class="eyebrow">PHP 8.2 · MYSQL · KOLAY KURULUM</div><?php if($success): ?><h1>Mağazanız hazır.</h1><div class="success">Yönetici hesabı oluşturuldu. Kurulum tekrar çalışmaya karşı kilitlendi.</div><p>Telefonunuz ve belirlediğiniz şifreyle giriş yapıp Hesabım → Yönetim Merkezi bölümünü açabilirsiniz.</p><p class="sub">Teslimat ücretlerini panelden girin. Örnek ürünler seçildi ise gerçek kataloğunuzu ekleyin. Güvenlik için <code>install.php</code> dosyasını hosting dosya yöneticisinden silebilirsiniz.</p><a class="button" href="<?=esc($site)?>">Mağazayı aç →</a><?php else: ?><h1>Güzel bir başlangıç yapalım.</h1><p class="sub">Hosting panelinde boş bir MySQL veritabanı ve o veritabanına yetkili kullanıcı oluşturun. Bilgileri burada girin; Node.js, Composer veya SSH gerekmez.</p><div class="checks"><?php foreach($checks as $name=>$ok):?><span class="check <?=$ok?'':'fail'?>"><?=$ok?'✓':'✕'?> <?=esc($name)?></span><?php endforeach?></div><?php if($error):?><p class="error" role="alert"><?=esc($error)?></p><?php endif?><form method="post"><input type="hidden" name="token" value="<?=esc($_SESSION['install_token'])?>"><h2>1. Site adresi</h2><label>Site adresiniz<input name="site_url" type="url" required value="<?=val('site_url',$suggest)?>" placeholder="https://siteadresiniz.com/demo"></label><p class="sub">Alt klasöre yüklediyseniz klasörü de yazın. Gerçek kullanımda HTTPS seçin.</p><h2>2. MySQL veritabanı</h2><div class="grid"><label>Veritabanı sunucusu<input name="db_host" required value="<?=val('db_host','localhost')?>"></label><label>Port<input name="db_port" type="number" min="1" max="65535" required value="<?=val('db_port','3306')?>"></label><label>Veritabanı adı<input name="db_name" required value="<?=val('db_name')?>"></label><label>Veritabanı kullanıcısı<input name="db_user" required value="<?=val('db_user')?>"></label></div><label>Veritabanı şifresi<input name="db_pass" type="password" autocomplete="off"></label><h2>3. İlk yönetici hesabı</h2><label>Yönetici telefon numarası<input name="phone" type="tel" required value="<?=val('phone')?>" placeholder="05xx xxx xx xx"></label><p class="sub">Şifremi unuttum mesajları bu numaranın WhatsApp ekranına yönlenir.</p><div class="grid"><label>İsim<input name="first_name" required minlength="2" value="<?=val('first_name')?>"></label><label>Soyisim<input name="last_name" required minlength="2" value="<?=val('last_name')?>"></label><label>İl<input name="city" required minlength="2" value="<?=val('city')?>"></label><label>İlçe<input name="district" required minlength="2" value="<?=val('district')?>"></label></div><label>Mahalle<input name="neighborhood" required minlength="2" value="<?=val('neighborhood')?>"></label><div class="grid"><label>Şifre<input name="password" type="password" autocomplete="new-password" required minlength="10" maxlength="200"></label><label>Şifre tekrar<input name="password_confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="200"></label></div><label><input type="checkbox" name="seed" value="1" <?=isset($_POST['seed'])||($_SERVER['REQUEST_METHOD']??'GET')!=='POST'?'checked':''?>> Başlangıç için örnek ürünleri de ekle</label><button class="button" <?=in_array(false,$checks,true)?'disabled':''?>>Kurulumu tamamla →</button></form><?php endif?></main></body></html>
